const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');
const { FakeDocument } = require('./browser-fakes.js');
const { installDetailDisclosureTemplateRuntime } = require('./workbench-detail-disclosure-runtime.js');
const { renderPageResultTables } = require('./page-result-table-harness.js');
const { createExploreModel, createMemoryRowStore } = require('./explore-section-fixtures.js');

const scripts = require('./workbench-scripts.js').compiledScriptsDir();

function loadWorkbench() {
    const workbench = {};
    const window = {};
    installDetailDisclosureTemplateRuntime(workbench);
    const context = vm.createContext({ console, URL, Promise, window, workbench, setTimeout });
    for (const filename of ['workbenchViews.js', 'workbenchRoutes.js', 'queryStream.js', 'workbenchApp.js', 'explore.js']) {
        vm.runInContext(fs.readFileSync(path.join(scripts, filename), 'utf8'), context, { filename });
    }
    window.workbench = context.workbench;
    return { workbench: context.workbench, window, context };
}

function flatten(template) {
    if (Array.isArray(template)) {
        return template.map(flatten).join('');
    }
    if (template && Array.isArray(template.strings)) {
        return template.strings.reduce((result, fragment, index) => result + fragment
            + (index < template.values.length ? flatten(template.values[index]) : ''), '');
    }
    if (template && template.tagName) {
        const attributes = Array.from(template.attributes.entries())
            .map(([name, value]) => `${name}="${value}"`).join(' ');
        return `<${template.tagName.toLowerCase()} ${attributes}>${flatten(template.template)}</${template.tagName.toLowerCase()}>`;
    }
    return template === null || typeof template === 'undefined' ? '' : String(template);
}

/** The rendered route template: the outlet's template when the shell renders the route into an outlet. */
function routeTemplate(workbench, mount) {
    const outlet = workbench.views.outletOf ? workbench.views.outletOf(mount) : null;
    return outlet && outlet.template ? outlet.template : mount.template;
}

function windowHarness(workbench, window, model) {
    const document = new FakeDocument();
    const mount = document.createElement('main');
    const listeners = new Map();
    const renders = [];
    const controls = { expanded: false, resource: '<urn:initial>', limit: '100', showDatatypes: true };
    window.innerHeight = 220;
    window.scrollY = 0;
    window.addEventListener = (name, listener) => listeners.set(name, listener);
    window.removeEventListener = name => listeners.delete(name);
    const geometry = document.createElement(model.viewId === 'saved-queries' ? 'div' : 'table');
    geometry.getBoundingClientRect = () => ({ top: -window.scrollY,
        height: model.rowCount * (model.viewId === 'saved-queries' ? 240 : 44) });
    const originalQuery = mount.querySelectorAll.bind(mount);
    mount.querySelectorAll = selector => selector.includes('data-workbench-row-table')
        || selector.includes('data-workbench-row-list') ? [geometry] : originalQuery(selector);

    const applyAttributes = (element, markup) => {
        for (const match of markup.matchAll(/([\w-]+)=(?:"([^"]*)"|'([^']*)'|([^\s>]+))/g)) {
            element.setAttribute(match[1], match[2] ?? match[3] ?? match[4]);
        }
    };
    const nodeValues = (template, nodes = []) => {
        if (template && template.tagName) {
            nodes.push(template);
        } else if (Array.isArray(template)) {
            template.forEach(value => nodeValues(value, nodes));
        } else if (template && template.values) {
            template.values.forEach(value => nodeValues(value, nodes));
        }
        return nodes;
    };
    const renderCard = (card, markup) => {
        for (const match of markup.matchAll(/<form\b([^>]*data-workbench-query-execution="true"[^>]*)>/g)) {
            const form = document.createElement('form');
            applyAttributes(form, match[1]);
            card.appendChild(form);
        }
    };
    const renderer = {
        nothing: '',
        html: runtime().html,
        render(template, target) {
            renders.push(target);
            target.template = template;
            const previousButtons = target.querySelectorAll('[data-workbench-explore-action]');
            target.children.slice().forEach(child => target.removeChild(child));
            nodeValues(template).forEach(node => target.appendChild(node));
            const markup = flatten(template);
            if (target === mount) {
                Object.assign(controls,
                    { expanded: false, resource: '<urn:initial>', limit: '100', showDatatypes: true });
                document.activeElement = null;
                const focusControl = document.createElement('input');
                focusControl.id = 'edited-control';
                target.appendChild(focusControl);
                if (!nodeValues(template).length) {
                    for (const match of markup.matchAll(/<article\b([^>]*)>([\s\S]*?)<\/article>/g)) {
                        const card = document.createElement('article');
                        applyAttributes(card, match[1]);
                        renderCard(card, match[2]);
                        target.appendChild(card);
                    }
                }
            } else if (target.tagName === 'ARTICLE') {
                renderCard(target, markup);
            }
            if (target === mount && nodeValues(template).length) { return; }
            for (const match of markup.matchAll(/<button\b([^>]*data-workbench-explore-action=[^>]*)>/g)) {
                const probe = document.createElement('button');
                applyAttributes(probe, match[1]);
                const button = previousButtons.find(candidate => target !== mount
                    && candidate.getAttribute('data-workbench-explore-action') === probe.getAttribute('data-workbench-explore-action')
                    && candidate.getAttribute('data-workbench-explore-group') === probe.getAttribute('data-workbench-explore-group')) || probe;
                applyAttributes(button, match[1]);
                target.appendChild(button);
            }
        }
    };
    return { document, mount, renderer, controls, listeners, renders, nodeValues };
}

test('saved-query bindings retain overlapping cards and dispose queries leaving the row window', async () => {
    const { workbench, window } = loadWorkbench();
    const rows = Array.from({ length: 300 }, (_unused, index) => [
        `urn:saved:${index}`, `Query ${index}`, 'me', 'SELECT * WHERE { ?s ?p ?o }', 'SPARQL', 'true', '100', '0'
    ]);
    const model = modelFor('saved-queries', []);
    model.vars = ['query', 'queryName', 'user', 'queryText', 'queryLn', 'infer', 'rowsPerPage', 'queryTimeout'];
    model.rowCount = rows.length;
    model.rowStore = { async read(start, count) { return rows.slice(start, start + count); } };
    const harness = windowHarness(workbench, window, model);
    const bindings = new Map();
    const disposed = [];
    workbench.queryStream.bindExecutionForms = root => {
        const forms = root.querySelectorAll('form[data-workbench-query-execution="true"]');
        for (const [form, binding] of bindings) {
            if (!forms.includes(form)) {
                disposed.push(binding.id);
                bindings.delete(form);
            }
        }
        forms.forEach(form => {
            if (!bindings.has(form)) {
                bindings.set(form, { id: form.id, submissions: 0 });
                form.addEventListener('submit', () => bindings.get(form).submissions++);
            }
        });
        return () => {
            bindings.forEach(binding => disposed.push(binding.id));
            bindings.clear();
        };
    };
    workbench.views.render(harness.mount, model, context, harness.renderer);
    const dispose = await workbench.views.bindRowWindows(harness.mount, model, context, harness.renderer);
    const firstForm = Array.from(bindings.keys()).find(form => form.id === 'saved-query-exec-0');
    assert.ok(firstForm, 'initial saved queries must have execution bindings');
    const firstBinding = bindings.get(firstForm);
    window.innerHeight = 660;
    await harness.listeners.get('resize')();
    assert.equal(bindings.get(firstForm), firstBinding,
        'resize must retain the controller for the same visible query');
    assert.equal(disposed.length, 0, 'resize must not cancel active visible queries');
    const overlappingForm = Array.from(bindings.keys()).find(form => form.id === 'saved-query-exec-4');
    const overlappingBinding = bindings.get(overlappingForm);
    window.scrollY = 8 * 240;
    await harness.listeners.get('scroll')();
    assert.equal(bindings.get(overlappingForm), overlappingBinding,
        'a query remaining in the shifted window must keep its own controller');
    assert.ok(disposed.includes('saved-query-exec-0'), 'removed queries must release their controllers');
    const laterForm = Array.from(bindings.keys()).find(form => form.id === 'saved-query-exec-8');
    assert.ok(laterForm, 'newly visible queries must acquire execution bindings');
    assert.notEqual(laterForm, firstForm, 'a former query form must not be repurposed for another query');
    laterForm.trigger('submit');
    assert.equal(bindings.get(laterForm).submissions, 1, 'new bindings must execute exactly once');
    assert.ok(bindings.size <= 80, 'card and controller retention must stay within the row window');
    dispose();
    assert.equal(bindings.size, 0);
    assert.equal(harness.listeners.size, 0);
});

test('Explore page controls use local section pages rather than viewport summary scans', () => {
    const { workbench } = loadWorkbench();
    const calls = [];
    const rows = Array.from({ length: 40 }, (_unused, index) => [{ kind: 'iri', value: `urn:type:${index}` }]);
    const model = createExploreModel({ sections: {
        types: { rows, totalRows: 80, count: '80' }
    }, controller: { page(key, direction) { calls.push([key, direction]); } } });
    const rendered = renderedExplore(workbench, model);
    const actions = bindings(rendered.template).filter(binding => binding.before.includes('@click='));
    const next = actions.find(binding => binding.after.includes('>Next</button>'));
    const previous = actions.find(binding => binding.after.includes('>Previous</button>'));

    assert.ok(next && previous, 'the current section page has both local navigation actions');
    assert.match(rendered.markup, /Showing 1–40 of 80 cached/);
    next.handler({ preventDefault() {} });
    previous.handler({ preventDefault() {} });
    assert.deepEqual(calls, [['types', 'next'], ['types', 'previous']]);
});

