function exploreLinks(template, result = []) {
    if (Array.isArray(template)) {
        template.forEach(value => exploreLinks(value, result));
    } else if (template && Array.isArray(template.values)) {
        template.values.forEach(value => exploreLinks(value, result));
    } else if (typeof template === 'string' && template.startsWith('explore?resource=')) {
        result.push(template);
    }
    return result;
}

function runtime() {
    return {
        nothing: '',
        html(strings, ...values) { return { strings: Array.from(strings), values }; },
        render(template, mount) { mount.template = template; }
    };
}

function modelFor(viewId, rows) {
    return {
        viewId,
        vars: ['subject', 'predicate', 'object'],
        rows,
        rowStart: 0,
        rowCount: rows.length,
        rowTopSpacer: 0,
        rowBottomSpacer: 0,
        rowStore: null,
        namespaceMap: {},
        links: [],
        metadata: { resource: '<urn:example:resource>' }
    };
}

const context = { basePath: '/rdf4j-workbench', repositoryId: 'a', workbench: {} };

function renderedExplore(workbench, model, pageContext = context, renderer = runtime()) {
    const host = {};
    workbench.views.renderExploreSections({
        querySelector(selector) { return selector === '#explore-section-output' ? host : null; }
    }, model, pageContext, renderer);
    return { host, template: host.template, markup: flatten(host.template).replace(/\s+/g, ' ') };
}

function bindings(template, result = []) {
    if (Array.isArray(template)) {
        template.forEach(value => bindings(value, result));
    } else if (template && Array.isArray(template.strings)) {
        template.values.forEach((value, index) => {
            if (typeof value === 'function') {
                result.push({ before: template.strings[index], after: template.strings[index + 1], handler: value });
            } else {
                bindings(value, result);
            }
        });
    }
    return result;
}

async function waitFor(predicate) {
    for (let attempt = 0; attempt < 200 && !predicate(); attempt++) {
        await new Promise(resolve => setImmediate(resolve));
    }
    assert.ok(predicate(), 'Explore section requests reached the expected state');
}

function sectionMarkup(markup, key) {
    const start = markup.indexOf(`data-explore-section=${key}`);
    assert.ok(start >= 0, `the ${key} section is rendered`);
    return markup.slice(start, markup.indexOf('</section>', start));
}
const terms = [
    [{ kind: 'iri', value: 'http://example.org/resource' }, '<http://example.org/resource>'],
    [{ kind: 'iri', value: 'https://example.org/café%20x?x=1&y=2#fragment' },
        '<https://example.org/café%20x?x=1&y=2#fragment>'],
    [{ kind: 'iri', value: 'urn:example:resource' }, '<urn:example:resource>'],
    [{ kind: 'bnode', value: 'node-1', reference: true }, '<_:node-1>'],
    [{ kind: 'bnode', value: '_:node-2', reference: true }, '<_:_:node-2>'],
    [{ kind: 'literal', value: 'plain "quoted" \\ value' }, String.raw`"plain \"quoted\" \\ value"`],
    [{ kind: 'literal', value: 'line\n\ttwo\rthree' }, '"line\\n\\ttwo\\rthree"'],
    [{ kind: 'literal', value: 'bonjour', language: 'fr' }, '"bonjour"@fr'],
    [{ kind: 'literal', value: '42', datatype: 'http://www.w3.org/2001/XMLSchema#integer' },
        '"42"^^<http://www.w3.org/2001/XMLSchema#integer>']
];

for (const viewId of ['contexts', 'types']) {
    test(`${viewId} RDF links serialize absolute IRIs and literal syntax before URL encoding`, () => {
        const { workbench } = loadWorkbench();
        const mount = {};
        const model = modelFor(viewId, terms.map(([term]) => [term]));
        model.vars = ['value'];
        workbench.views.render(mount, model, context, runtime());
        const links = exploreLinks(mount.template);
        // Graphs rows also carry an Explore action next to the linked name (plan task M5.2).
        const perRow = viewId === 'contexts' ? 2 : 1;
        assert.equal(links.length, terms.length * perRow);
        terms.forEach(([term, expected], index) => {
            for (let copy = 0; copy < perRow; copy++) {
                const decoded = new URL(links[index * perRow + copy], 'https://workbench.test/').searchParams.get('resource');
                assert.equal(decoded, expected, `${viewId} must preserve ${term.kind} RDF syntax`);
            }
        });
    });
}

for (const viewId of ['contexts', 'types']) {
    test(`${viewId} browse links require certified blank-node result identity`, () => {
        const { workbench } = loadWorkbench();
        const untrusted = { kind: 'bnode', value: 'unverified', scope: 'old-server-result' };
        const trusted = { kind: 'bnode', value: 'stored', reference: true };
        const model = modelFor(viewId, [[untrusted], [trusted]]);
        model.vars = [viewId === 'contexts' ? 'context' : 'type'];
        const mount = {};
        workbench.views.render(mount, model, context, runtime());
        const links = exploreLinks(mount.template);
        assert.equal(links.filter(link => link.includes(encodeURIComponent('<_:unverified>'))).length, 0,
            'an unverified result label must not introduce a fixed-reference request');
        assert.equal(links.filter(link => link.includes(encodeURIComponent('<_:stored>'))).length,
            viewId === 'contexts' ? 2 : 1, 'certified resources retain their navigation actions');
        assert.match(flatten(mount.template), /_:unverified/, 'unverified values remain visible');
        assert.doesNotMatch(flatten(mount.template), /clear\?context=%3C_%3Aunverified%3E/,
            'an unverified graph label must not become a Clear operand');
    });
}

test('Explore summary links and type chips preserve result provenance recursively', () => {
    const { workbench } = loadWorkbench();
    const iri = value => ({ kind: 'iri', value });
    const untrusted = { kind: 'bnode', value: 'unverified', scope: 'old-server-result' };
    const trusted = { kind: 'bnode', value: 'stored', reference: true };
    const nested = { kind: 'triple', subject: trusted, predicate: iri('urn:p'), object: untrusted };
    const model = createExploreModel({ sections: {
        types: { rows: [[untrusted], [trusted], [nested]] },
        subClasses: { rows: [[untrusted], [trusted]] }
    } });
    const rendered = renderedExplore(workbench, model);
    const links = exploreLinks(rendered.template);
    assert.equal(links.filter(link => decodeURIComponent(link).includes('<_:unverified>')).length, 0,
        'neither value sections nor nested triple terms promote an unverified blank node');
    assert.equal(links.filter(link => link === 'explore?resource=' + encodeURIComponent('<_:stored>')).length, 2,
        'certified terms remain reusable across independent value sections');
    assert.match(rendered.markup, /_:unverified/);
});

